        head++;

        if (x > 0 && grid[x-1][y] != '*' && grid[x-1][y] - '0' <= f) {
            grid[x-1][y] = '*'; qx[tail] = x-1; qy[tail] = y; tail++;
        }
        if (x < n-1 && grid[x+1][y] != '*' && grid[x+1][y] - '0' <= f) {
            grid[x+1][y] = '*'; qx[tail] = x+1; qy[tail] = y; tail++;
        }
        if (y > 0 && grid[x][y-1] != '*' && grid[x][y-1] - '0' <= f) {
            grid[x][y-1] = '*'; qx[tail] = x; qy[tail] = y-1; tail++;
        }
        if (y < n-1 && grid[x][y+1] != '*' && grid[x][y+1] - '0' <= f) {
            grid[x][y+1] = '*'; qx[tail] = x; qy[tail] = y+1; tail++;
        }
    }

    for (int i = 0; i < n; i++) puts(grid[i]);

    return 0;
}
